def solve(g):
    if not g or not g[0]: return 0
    dp=[0]*len(g[0])
    dp[0]=1
    for row in g:
        for c,x in enumerate(row): dp[c]=0 if x else dp[c]+(dp[c-1] if c else 0)
    return dp[-1]
